package com.fintrack.khmtomnenh.quotation.service; import com.fintrack.khmtomnenh.auth.entity.Auth; import com.fintrack.khmtomnenh.product.repository.ProductRepository; import com.fintrack.khmtomnenh.quotation.dto.QuotationDto; import com.fintrack.khmtomnenh.quotation.entity.Quotation; import com.fintrack.khmtomnenh.quotation.repository.QuotationRepository; import com.fintrack.khmtomnenh.quotationitem.entity.QuotationItem; import com.fintrack.khmtomnenh.rfq.entity.Rfq; import com.fintrack.khmtomnenh.rfq.repository.RfqRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.util.*;
@Service @RequiredArgsConstructor public class QuotationService {private final QuotationRepository repo;private final RfqRepository rfqs;private final ProductRepository products;public List<Quotation> supplierMine(Auth a){return repo.findBySupplierIdOrderByCreatedAtDesc(a.getId());}public List<Quotation> buyerMine(Auth a){return repo.findByRfqBuyerIdOrderByCreatedAtDesc(a.getId());}public Quotation get(Long id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("Quotation not found"));}@Transactional public Quotation create(QuotationDto d,Auth a){Rfq r=rfqs.findById(d.rfqId()).orElseThrow(()->new IllegalArgumentException("RFQ not found"));if(!"OPEN".equals(r.getStatus()))throw new IllegalArgumentException("RFQ is not open");Quotation q=Quotation.builder().rfq(r).supplier(a).notes(d.notes()).totalAmount(BigDecimal.ZERO).build();BigDecimal total=BigDecimal.ZERO;for(QuotationDto.Item x:d.items()){var p=products.findById(x.productId()).orElseThrow(()->new IllegalArgumentException("Product not found"));if(r.getItems().stream().noneMatch(i->i.getProduct().getId().equals(p.getId())))throw new IllegalArgumentException("Product is not in RFQ");total=total.add(x.unitPrice().multiply(BigDecimal.valueOf(x.quantity())));q.getItems().add(QuotationItem.builder().quotation(q).product(p).quantity(x.quantity()).unitPrice(x.unitPrice()).build());}q.setTotalAmount(total);return repo.save(q);}public void assertBuyer(Quotation q,Auth a){if(!q.getRfq().getBuyer().getId().equals(a.getId()))throw new AccessDeniedException("Not quotation owner");}}
